trig={"changed_main":False,"reserve_used":False,"disputed":False,"reason":""}
total=0; counts={"changed_main":0,"reserve_used":0,"disputed":0}
for cid in IDS:
    trad,sysu,pred,basis,conf = D[cid]
    full_basis = f"tradition: {trad}\nsystems_used: {sysu}\n{basis}\n[收束留痕] 已载面表与断项过闸已在上文随断执行；R61-REV1（calibration第六节）应期二路复推/粒度核已在相关例留痕，无应期或无具体断项之例已在上文明记不适用。calibration第五节R59-REV1已经R60判读标失效存档、不再强制，本轮未据其设新段落。trigger：本例非六爻，三项全false、reason空串。"
    obj={"case_id":cid,"prediction_text":pred,"basis":full_basis,"confidence":conf,"trigger":dict(trig)}
    p=os.path.join(OUT,cid+".json")
    with open(p,"w",encoding="utf-8") as f:
        json.dump(obj,f,ensure_ascii=False,indent=1)
    total+=os.path.getsize(p)
# validation per exact id list
for cid in IDS:
    p=os.path.join(OUT,cid+".json")
    o=json.load(open(p,encoding="utf-8"))
    assert set(o)== {"case_id","prediction_text","basis","confidence","trigger"}, cid
    assert o["case_id"]==cid and isinstance(o["confidence"],(int,float)) and 0<=o["confidence"]<=1
    t=o["trigger"]; assert set(t)=={"changed_main","reserve_used","disputed","reason"}
    assert all(isinstance(t[k],bool) for k in ("changed_main","reserve_used","disputed")) and isinstance(t["reason"],str)
    for k in counts: counts[k]+= 1 if t[k] else 0
print("written",len(IDS),"total_bytes",total,"trigger_counts",counts)
